function validate([root, val]) {
  const values = root.filter(v => v !== null);
  if (root[0] === null || values.length < 1 || values.length > 100) return 'The tree has 1 to 100 nodes.';
  if (values.some(v => !Number.isInteger(v) || v < 1 || v > 100)) return 'Every node value is between 1 and 100.';
  if (new Set(values).size !== values.length) return 'Node values must be distinct.';
  if (!Number.isInteger(val) || val < 1 || val > 100) return 'val is between 1 and 100.';
  if (values.includes(val)) return 'val must differ from every value in the tree.';
  // Walk the level order: every child must be smaller than its parent.
  const parents = [root[0]];
  let i = 1;
  for (let p = 0; p < parents.length && i < root.length; p++) {
    for (let side = 0; side < 2 && i < root.length; side++, i++) {
      if (root[i] === null) continue;
      if (root[i] > parents[p]) return 'Each node must be larger than its children (a maximum tree).';
      parents.push(root[i]);
    }
  }
  return null;
}

