function insertIntoMaxTree(root, val) {
  // Recover the hidden list with an in-order walk, append val, and rebuild the tree from scratch.
  const list = [];
  const walk = (node) => {
    if (!node) return;
    walk(node.left);
    list.push(node.val);
    walk(node.right);
  };
  walk(root);
  list.push(val);
  const build = (lo, hi) => {
    if (lo > hi) return null;
    let top = lo;
    for (let i = lo + 1; i <= hi; i++) if (list[i] > list[top]) top = i;
    return new TreeNode(list[top], build(lo, top - 1), build(top + 1, hi));
  };
  return build(0, list.length - 1);
}

