function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 80 + Math.floor(rand() * 20) : 1 + Math.floor(rand() * 8);
  const shuffle = (list) => {
    for (let i = list.length - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [list[i], list[j]] = [list[j], list[i]];
    }
    return list;
  };
  // Pick n + 1 distinct values from 1..100; one becomes val and the rest form the hidden list a.
  const picked = shuffle(Array.from({ length: 100 }, (_, i) => i + 1)).slice(0, n + 1);
  const mode = rand();
  if (mode < 0.35) picked.sort((x, y) => x - y);
  // val is the largest value (new root), the smallest (deepest insert), or random.
  const val = mode < 0.2 ? picked.pop() : mode < 0.35 ? picked.shift() : picked.pop();
  const a = shuffle(picked);
  // Sorted lists give long chains to the left or right.
  const shape = rand();
  if (shape < 0.15) a.sort((x, y) => x - y);
  else if (shape < 0.3) a.sort((x, y) => y - x);
  const build = (lo, hi) => {
    if (lo > hi) return null;
    let top = lo;
    for (let i = lo + 1; i <= hi; i++) if (a[i] > a[top]) top = i;
    return { val: a[top], left: build(lo, top - 1), right: build(top + 1, hi) };
  };
  // Level-order serialisation with null for missing children, trailing nulls removed.
  const out = [];
  const queue = [build(0, a.length - 1)];
  for (let q = 0; q < queue.length; q++) {
    const node = queue[q];
    if (node === null) { out.push(null); continue; }
    out.push(node.val);
    queue.push(node.left, node.right);
  }
  while (out[out.length - 1] === null) out.pop();
  return [out, val];
}
